import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter understood by {@link CustomerRepository}.
 *
 * @param name     free-text search terms; a customer matches when every
 *                 whitespace-separated term is a substring of the first name
 *                 or the last name, ignoring case and accents. Blank matches
 *                 every customer.
 * @param statuses statuses a customer must have one of; empty matches every
 *                 customer
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** The name filter, split on whitespace into normalized, non-blank terms. */
    public List<String> nameTerms() {
        return Arrays.stream(name.trim().split("\\s+"))
                .filter(term -> !term.isBlank())
                .map(CustomerFilter::normalize)
                .toList();
    }

    public boolean matches(Customer customer) {
        return matchesName(customer) && matchesStatus(customer);
    }

    private boolean matchesName(Customer customer) {
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    /** Lowercases and strips diacritics, so accents and case do not matter when matching. */
    static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase();
    }
}
