+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+
+/**
+ * Real-browser check of what the browserless suite cannot see: what typing
+ * costs the backend, and what ends up in the address bar. Not named
+ * {@code *Test}, so {@code mvn test} does not run it; run it directly from an
+ * IDE or with {@code mvn -o test -Dtest=CustomerListViewBrowserIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingDebouncesAndUpdatesGridAndUrl() {
+        queryLog.clear();
+
+        Locator nameInput = page.locator("input[placeholder='Filter by name']");
+        nameInput.pressSequentially("aaltonen", new Locator.PressSequentiallyOptions().setDelay(30));
+        page.waitForTimeout(600);
+
+        assertEquals(15, GridElement.get(page).getTotalRowCount());
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing 8 characters cost " + queryLog.pageQueries().size() + " page queries");
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing 8 characters cost " + queryLog.countQueries().size() + " count queries");
+        assertTrue(page.url().contains("?name=aaltonen"),
+                "Address bar was " + page.url());
+    }
+
+    @Test
+    void selectingStatusesUpdatesUrlWithLiteralComma() {
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusFilter.selectItems("ACTIVE", "CLOSED");
+        page.waitForTimeout(300);
+
+        assertEquals(333, GridElement.get(page).getTotalRowCount());
+        assertTrue(page.url().endsWith("?status=ACTIVE,CLOSED"),
+                "Address bar was " + page.url());
+    }
+
+    @Test
+    void openingWithQueryParametersAppliesTheFilter() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForTimeout(300);
+
+        assertEquals("vir", page.locator("input[placeholder='Filter by name']").inputValue());
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusFilter.assertSelectedItems("ACTIVE", "CLOSED");
+    }
+}
